EMBEDDED_IMAGE_BASE64 = b"" 
GIT_IMAGE_BASE64 = b""  

def load_embedded_pixmap():
    try:
        if not EMBEDDED_IMAGE_BASE64:
            return QPixmap()
        byte_array = QByteArray.fromBase64(EMBEDDED_IMAGE_BASE64)
        pixmap = QPixmap()
        pixmap.loadFromData(byte_array)
        return pixmap
    except Exception:
        return QPixmap()

GITHUB_URL = "https://github.com/Ilyukha211/SpectreLine"


def resource_path(name):
    base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base, name)


def load_git_pixmap():
    try:
        path = resource_path("git.png")
        if os.path.isfile(path):
            pm = QPixmap(path)
            if not pm.isNull():
                return pm
        if GIT_IMAGE_BASE64:
            pm = QPixmap()
            if pm.loadFromData(QByteArray.fromBase64(GIT_IMAGE_BASE64)):
                return pm
    except Exception:
        pass
    return QPixmap()


