SCAN_EXTENSIONS = ('.exe', '.dll', '.asi', '.rom', '.jar', '.lnk', '.cfg', '.ini', '.txt')

SKIP_DIR_TOKENS = (
    "microsoft office", "office16", "git", "frst", "blender",
    "epic games", "steam\\steamapps", "nvidia", "intel", "amd",
    "windows\\winsxs", "$recycle.bin", "system volume information",
    "google\\chrome", "mozilla\\firefox", "discord", "telegram desktop",
    "adobe", "common files", "windowsapps", ".minecraft", "ollama"
)
_WRAPPED_SKIP_TOKENS = tuple("\\" + t + "\\" for t in SKIP_DIR_TOKENS)

SAFE_FILE_NAMES = {
    "ggml-cpu-sapphirerapids.dll", "mercurial.py", "template.js",
    "primordials.js", "dxcore.dll"
}

SIGNATURE_RE = re.compile(
    "|".join(re.escape(s) for s in sorted(set(ULTIMATE_CHEAT_SIGNATURES), key=len, reverse=True))
)

FILE_ATTRIBUTE_REPARSE_POINT = 0x400
FILE_ATTRIBUTE_CLOUD_PLACEHOLDER = 0x00040000 | 0x00400000 


def is_skipped_dir(path):
    norm = "\\" + path.lower().replace("/", "\\").strip("\\") + "\\"
    return any(tok in norm for tok in _WRAPPED_SKIP_TOKENS)


class ShadowLabel(QLabel):
    """Текст із м'якою тінню. Малюється вручну: набагато легше за QGraphicsDropShadowEffect,
    який перемальовував і розмивав текст на кожному кадрі анімації та гальмував інтерфейс."""

    def __init__(self, text="", color="#ffffff", parent=None):
        super().__init__(text, parent)
        self.text_color = QColor(color)
        self.setStyleSheet("background: transparent;")

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setFont(self.font())
        flags = self.alignment().value | Qt.TextFlag.TextWordWrap.value
        rect = QRectF(self.rect())
        for dx, dy, alpha in ((0, 2, 90), (1, 2, 140), (-1, 2, 140), (0, 1, 230)):
            painter.setPen(QColor(0, 0, 0, alpha))
            painter.drawText(rect.translated(dx, dy), flags, self.text())
        painter.setPen(self.text_color)
        painter.drawText(rect, flags, self.text())
        painter.end()


class PercentBar(QProgressBar):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setRange(0, 1000)
        self.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))

    def text(self):
        v = self.value()
        if v >= 1000:
            return "100%"
        return f"{v / 10:.1f}%"


class Enhanced3DTriangle:
    def __init__(self, w, h):
        self.x = random.uniform(320, 360)
        self.y = random.uniform(80, max(100, h - 50))
        self.vx = random.uniform(2.5, 4.8)
        self.vy = random.uniform(-1.2, 1.2)
        self.size = random.uniform(10, 22)
        self.angle_x = random.uniform(0, 360)
        self.angle_y = random.uniform(0, 360)
        self.angle_z = random.uniform(0, 360)
        self.v_x = random.uniform(-2.0, 2.0)
        self.v_y = random.uniform(-2.2, 2.2)
        self.v_z = random.uniform(-3.0, 3.0)
        self.alpha = random.uniform(200, 255)
        self.fade_speed = random.uniform(1.0, 1.8)

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt
        self.angle_x += self.v_x * dt
        self.angle_y += self.v_y * dt
        self.angle_z += self.v_z * dt
        self.alpha -= self.fade_speed * dt

    def bounds(self):
        r = int(self.size + 4)
        return QRect(int(self.x) - r, int(self.y) - r, 2 * r, 2 * r)


class ParticleOverlayWidget(QWidget):
    
    SPEED = 0.2

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.particles = []
        self._clock = QElapsedTimer()
        self._timer = QTimer(self)
        self._timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._step)

    def showEvent(self, event):
        super().showEvent(event)
        self._clock.start()
        self._timer.start()

    def hideEvent(self, event):
        super().hideEvent(event)
        self._timer.stop()

    def _step(self):
        dt = min(3.0, self._clock.restart() / 16.0) * self.SPEED
        w, h = max(1, self.width()), max(1, self.height())
        dirty = QRect()

        if random.random() < 0.8 * dt:
            p = Enhanced3DTriangle(w, h)
            self.particles.append(p)
            dirty = dirty.united(p.bounds())

        alive = []
        for p in self.particles:
            dirty = dirty.united(p.bounds())
            p.update(dt)
            if p.alpha <= 0 or p.x > w + 50:
                continue
            dirty = dirty.united(p.bounds())
            alive.append(p)
        self.particles = alive

        if not dirty.isNull():
            self.update(dirty.adjusted(-2, -2, 2, 2))

    def paintEvent(self, event):
        if not self.particles:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        for p in self.particles:
            painter.save()
            painter.translate(p.x, p.y)

            scale_x = math.cos(math.radians(p.angle_y))
            scale_y = math.sin(math.radians(p.angle_x))
            painter.scale(max(0.2, abs(scale_x)), max(0.2, abs(scale_y)))
            painter.rotate(p.angle_z)

            alpha_val = int(max(0, min(255, p.alpha)))

            gradient = QLinearGradient(0, -p.size, 0, p.size)
            gradient.setColorAt(0.0, QColor(255, 255, 255, alpha_val))
            gradient.setColorAt(0.5, QColor(220, 235, 255, int(alpha_val * 0.8)))
            gradient.setColorAt(1.0, QColor(150, 180, 220, int(alpha_val * 0.3)))

            painter.setPen(QPen(QColor(255, 255, 255, alpha_val), 1.2))
            painter.setBrush(QBrush(gradient))

            path = QPainterPath()
            s = p.size
            path.moveTo(0, -s)
            path.lineTo(s * 0.866, s * 0.5)
            path.lineTo(-s * 0.866, s * 0.5)
            path.closeSubpath()

            painter.drawPath(path)
            painter.restore()
        painter.end()


class LiveScanWorker(QThread):
    status_signal = pyqtSignal(str)
    path_signal = pyqtSignal(str)
    progress_signal = pyqtSignal(int)
    stats_signal = pyqtSignal(int, int, int)
    threat_found_signal = pyqtSignal(str)
    finished_signal = pyqtSignal(bool)  

    EMIT_INTERVAL = 0.08       
    YIELD_INTERVAL = 0.02      

    def __init__(self, target_selection):
        super().__init__()
        self.target_selection = target_selection
        self.total_entries = 0
        self.checked_files = 0
        self.scanned_dirs = 0
        self.done_bytes = 0
        self.total_bytes = 1
        self.progress_floor = 0
        self.progress_ceiling = 99
        self._last_emit = 0.0
        self._last_yield = 0.0
        self._last_progress = 0

    @staticmethod
    def is_safe(full_path, file_name):
        if file_name.lower() in SAFE_FILE_NAMES:
            return True
        return bool(full_path) and is_skipped_dir(os.path.dirname(full_path))

    @staticmethod
    def read_shortcut(lnk_path):
        try:
            with open(lnk_path, 'rb') as f:
                content = f.read(16384)
            return content.decode('utf-16le', errors='ignore') + " " + content.decode('latin1', errors='ignore')
        except Exception:
            return ""

    def _yield_gil(self):
        now = time.monotonic()
        if now - self._last_yield >= self.YIELD_INTERVAL:
            time.sleep(0.002)
            self._last_yield = time.monotonic()

    def _tick(self, current_path="", force=False):
        now = time.monotonic()
        if not force and now - self._last_emit < self.EMIT_INTERVAL:
            return
        self._last_emit = now
        frac = min(1.0, self.done_bytes / max(1, self.total_bytes))
        span = self.progress_ceiling - self.progress_floor
        prog = int((self.progress_floor + frac * span) * 10)  # проміле: 0..1000
        prog = max(self._last_progress, min(self.progress_ceiling * 10, prog))  # лише вперед, максимум 99.0% до кінця
        self._last_progress = prog
        self.progress_signal.emit(prog)
        self.stats_signal.emit(self.total_entries, self.checked_files, self.scanned_dirs)
        if current_path:
            self.path_signal.emit(current_path)

    def _iter_tree(self, top):

        stack = [top]
        while stack:
            if self.isInterruptionRequested():
                return
            current = stack.pop()
            try:
                with os.scandir(current) as it:
                    entries = list(it)
            except OSError:
                continue
            for entry in entries:
                try:
                    st = entry.stat(follow_symlinks=False)
                    attrs = getattr(st, "st_file_attributes", 0)
                    if entry.is_dir(follow_symlinks=False):
                        if attrs & FILE_ATTRIBUTE_REPARSE_POINT:
                            continue
                        if is_skipped_dir(entry.path):
                            continue
                        stack.append(entry.path)
                        yield ("dir", entry.path, entry.name, 0, attrs)
                    elif entry.is_file(follow_symlinks=False):
                        yield ("file", entry.path, entry.name, st.st_size, attrs)
                except OSError:
                    continue

    def _scan_processes(self):
        self.status_signal.emit("Scanning active system processes...")
        try:
            procs = list(psutil.process_iter(['pid', 'name', 'exe']))
        except Exception:
            return
        for idx, proc in enumerate(procs):
            if self.isInterruptionRequested():
                return
            self.total_entries += 1
            try:
                pinfo = proc.info
                pname = (pinfo['name'] or "")
                pexe = (pinfo['exe'] or "")
                if self.is_safe(pexe, pname):
                    continue
                m = SIGNATURE_RE.search(pname.lower()) or SIGNATURE_RE.search(pexe.lower())
                if m:
                    self.threat_found_signal.emit(
                        f"[PROCESS] Name: {pname} (PID: {pinfo['pid']}) | Match: {m.group(0).upper()}"
                    )
            except Exception:
                pass
            if idx % 40 == 0:
                self._yield_gil()
        self.stats_signal.emit(self.total_entries, self.checked_files, self.scanned_dirs)

    def _scan_registry(self):
        self.status_signal.emit("Scanning Windows Registry traces...")
        run_keys = [
            (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run"),
            (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\RunOnce"),
            (winreg.HKEY_LOCAL_MACHINE, r"Software\Microsoft\Windows\CurrentVersion\Run"),
            (winreg.HKEY_LOCAL_MACHINE, r"Software\Microsoft\Windows\CurrentVersion\RunOnce"),
            (winreg.HKEY_LOCAL_MACHINE, r"Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"),
        ]
        for hkey, subkey in run_keys:
            try:
                key = winreg.OpenKey(hkey, subkey, 0, winreg.KEY_READ)
            except OSError:
                continue
            try:
            
                i = 0
                while True:
                    try:
                        value_name, value_data, _ = winreg.EnumValue(key, i)
                    except OSError:
                        break
                    i += 1
                    self.total_entries += 1
                    blob = f"{value_name} {value_data}".lower()
                    m = SIGNATURE_RE.search(blob)
                    if m:
                        self.threat_found_signal.emit(
                            f"[REGISTRY] {subkey}\\{value_name} = {str(value_data)[:120]} | Match: {m.group(0).upper()}"
                        )
            finally:
                winreg.CloseKey(key)

    def _resolve_targets(self):
        if self.target_selection == "FULL":
            targets = []
            for p in psutil.disk_partitions(all=False):
                try:
                    if 'fixed' in p.opts.lower() and os.path.exists(p.device):
                        targets.append(p.device)
                except Exception:
                    pass
            return targets
        return [self.target_selection] if os.path.isdir(self.target_selection) else []

    def _estimate_total(self, target):
    
        if os.path.splitdrive(target)[1].strip("\\/") == "":
            try:
                return max(1, psutil.disk_usage(target).used)
            except Exception:
                return 1

        total = 0
        for kind, _path, _name, size, _attrs in self._iter_tree(target):
            if kind == "file":
                total += size
            self._yield_gil()
        return max(1, total)

    def _scan_target(self, target, expected_bytes, expected_before):
        current_dir_shown = ""
        for kind, path, name, size, attrs in self._iter_tree(target):
            self.total_entries += 1

            if kind == "dir":
                self.scanned_dirs += 1
                current_dir_shown = path
                m = SIGNATURE_RE.search(name.lower())
                if m:
                    self.threat_found_signal.emit(f"[FOLDER] Path: {path} | Match: {m.group(0).upper()}")
            else:
                self.done_bytes += size
                low = name.lower()
                if low.endswith(SCAN_EXTENSIONS) and low not in SAFE_FILE_NAMES:
                    self.checked_files += 1
                    m = SIGNATURE_RE.search(low)
                    if m:
                        self.threat_found_signal.emit(f"[FILE] Path: {path} | Match: {m.group(0).upper()}")
                    elif low.endswith(".lnk") and not (attrs & FILE_ATTRIBUTE_CLOUD_PLACEHOLDER):
                        target_data = self.read_shortcut(path).lower()
                        m = SIGNATURE_RE.search(target_data)
                        if m:
                            self.threat_found_signal.emit(
                                f"[SHORTCUT] Lnk: {path} -> target contains: {m.group(0).upper()}"
                            )

            self._tick(current_dir_shown)
            self._yield_gil()
            if self.isInterruptionRequested():
                return


        self.done_bytes = max(self.done_bytes, expected_before + expected_bytes)

    def run(self):
        completed = False
        try:
            self.setPriority(QThread.Priority.LowPriority)  
            completed = self._run_scan()
        except Exception as exc:
            self.status_signal.emit(f"Scan stopped due to an error: {exc}")
        finally:
            self.finished_signal.emit(completed)

    def _run_scan(self):
        self.status_signal.emit("Initializing smart system inspection...")
        self.progress_signal.emit(10)
        self._last_progress = 10
        self.progress_floor = 1

        if self.target_selection == "FULL":
            self._scan_processes()
            if self.isInterruptionRequested():
                return False
            self.progress_signal.emit(30)
            self._scan_registry()
            if self.isInterruptionRequested():
                return False
            self.progress_signal.emit(50)
            self._last_progress = 50
            self.progress_floor = 5

        targets = self._resolve_targets()
        if not targets:
            self.status_signal.emit("Selected location is unavailable.")
            return False

        self.status_signal.emit("Measuring scan size...")
        expected = []
        for t in targets:
            expected.append(self._estimate_total(t))
            if self.isInterruptionRequested():
                return False
        self.total_bytes = max(1, sum(expected))

        self.status_signal.emit("Scanning files, folders & shortcuts...")
        before = 0
        for target, exp in zip(targets, expected):
            self._scan_target(target, exp, before)
            if self.isInterruptionRequested():
                return False
            before += exp

        self._tick(force=True)
        self.progress_signal.emit(1000)
        self.stats_signal.emit(self.total_entries, self.checked_files, self.scanned_dirs)
        self.status_signal.emit("System inspection completed successfully.")
        return True


class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("SpectreLine v1.0")
        self.setFixedSize(1050, 700)
        self.steam_loaded = False
        self.worker = None
        self.init_ui()
        self.apply_dark_stylesheets()

    def closeEvent(self, event):
    
        if self.worker is not None and self.worker.isRunning():
            self.worker.requestInterruption()
            self.worker.wait(3000)
        super().closeEvent(event)

    def init_ui(self):
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(0, 0, 0, 0)
        main_layout.setSpacing(0)

        self.tabs = QTabWidget()
        self.tabs.currentChanged.connect(self.on_tab_changed)
        main_layout.addWidget(self.tabs)

        self.stats_lbl = QLabel("Entries: 0    Files: 0    Directories: 0")
        self.stats_lbl.setFont(QFont("Segoe UI", 9))
        self.stats_lbl.setStyleSheet("color: #8b949e; background-color: #0d1117; padding: 6px 12px; border-top: 1px solid #30363d;")
        main_layout.addWidget(self.stats_lbl)

        central_widget = QWidget()
        central_widget.setLayout(main_layout)
        self.setCentralWidget(central_widget)

        self.tab_scanner = QWidget()
        self.setup_scanner_tab()
        self.tabs.addTab(self.tab_scanner, "Drive / Scan")

        self.tab_explorer = QWidget()
        self.setup_explorer_tab()
        self.tabs.addTab(self.tab_explorer, "File Explorer")

        self.tab_steam = QWidget()
        self.setup_steam_tab()
        self.tabs.addTab(self.tab_steam, "Steam Accounts")

        self.tab_processes = QWidget()
        self.setup_processes_tab()
        self.tabs.addTab(self.tab_processes, "Processes")

        self.tab_tools = QWidget()
        self.setup_tools_tab()
        self.tabs.addTab(self.tab_tools, "Utilities")

        self.tab_info = QWidget()
        self.setup_info_tab()
        self.tabs.addTab(self.tab_info, "Information")

