    def make_copy_icon(self):
        pix = QPixmap(32, 32)
        pix.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pix)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(QColor("#c9d1d9"))
        pen.setWidth(2)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawRoundedRect(11, 4, 17, 19, 4, 4)
        painter.setBrush(QColor("#161b22"))
        painter.drawRoundedRect(4, 10, 17, 19, 4, 4)
        painter.end()
        return QIcon(pix)

    def copy_threats(self):
        lines = [self.threat_list.item(i).text() for i in range(self.threat_list.count())]
        if not lines:
            QToolTip.showText(self.copy_btn.mapToGlobal(self.copy_btn.rect().bottomLeft()), "Nothing to copy", self.copy_btn)
            return
        QApplication.clipboard().setText("\n".join(lines))
        QToolTip.showText(self.copy_btn.mapToGlobal(self.copy_btn.rect().bottomLeft()), "Copied!", self.copy_btn)

    def set_progress(self, value):
        current = self.progress_bar.value()
        if value <= current:
            return
        self.progress_anim.stop()
        self.progress_anim.setStartValue(current)
        self.progress_anim.setEndValue(value)
        self.progress_anim.start()

    def set_current_path(self, path):
        text = "Checking: " + path
        metrics = self.desc_lbl.fontMetrics()
        self.desc_lbl.setText(metrics.elidedText(text, Qt.TextElideMode.ElideMiddle, self.desc_lbl.width() - 10))

    def update_stats(self, entries, files, dirs):
        self.stats_lbl.setText(f"Entries: {entries}    Files: {files}    Directories: {dirs}")

    def start_scan(self):
        if self.worker is not None and self.worker.isRunning():
            return

        target_selection = self.scan_target_combo.currentData()
        if target_selection != "FULL" and not os.path.isdir(target_selection):
            QMessageBox.warning(self, "Scan", f"Location is not available:\n{target_selection}")
            return

        self.start_scan_btn.setEnabled(False)
        self.start_scan_btn.setText("Scanning...")
        self.scan_target_combo.setEnabled(False)
        self.threat_panel.setVisible(True)
        self.threat_list.clear()
        self.threat_count = 0
        self.progress_anim.stop()
        self.progress_bar.setValue(0)
        self.desc_lbl.setText("Preparing scan...")
        self.update_stats(0, 0, 0)

        self.worker = LiveScanWorker(target_selection)
        self.worker.status_signal.connect(self.title_lbl.setText)
        self.worker.path_signal.connect(self.set_current_path)
        self.worker.progress_signal.connect(self.set_progress)
        self.worker.stats_signal.connect(self.update_stats)
        self.worker.threat_found_signal.connect(self.add_threat_item)
        self.worker.finished_signal.connect(self.scan_finished)
        self.worker.start()

    MAX_LISTED_THREATS = 3000

    def add_threat_item(self, text):
        self.threat_count += 1
        if self.threat_count > self.MAX_LISTED_THREATS:
            if self.threat_count == self.MAX_LISTED_THREATS + 1:
                item = QListWidgetItem("[!] Too many matches - the list is truncated. Narrow the scan target.")
                item.setForeground(QColor("#d29922"))
                self.threat_list.addItem(item)
            return
        item = QListWidgetItem(text)
        item.setForeground(QColor("#ff7b72"))
        self.threat_list.addItem(item)
        self.threat_list.scrollToBottom()

    def scan_finished(self, completed=True):
        self.start_scan_btn.setEnabled(True)
        self.start_scan_btn.setText("Start Full Scan")
        self.scan_target_combo.setEnabled(True)
        if completed:
            self.progress_anim.stop()
            self.progress_bar.setValue(1000)
            self.desc_lbl.setText("Scan finished. Review findings below.")
            if self.threat_count == 0:
                item = QListWidgetItem("[+] Clean System: No cheats or loaders detected.")
                item.setForeground(QColor("#ffffff"))
                self.threat_list.addItem(item)
        else:
            self.desc_lbl.setText("Scan was not completed.")

