    def populate_drives(self):
        self.drive_combo.clear()
        self.drive_combo.addItem("User Home", os.path.expandvars(r'%USERPROFILE%'))
        try:
            for partition in psutil.disk_partitions():
                if 'fixed' in partition.opts.lower() or 'cdrom' not in partition.opts.lower():
                    self.drive_combo.addItem(partition.device, partition.device)
        except Exception:
            pass

    def change_drive(self, index):
        path = self.drive_combo.itemData(index)
        if path and os.path.exists(path):
            self.set_explorer_path(path)

    def set_explorer_path(self, path):
        if os.path.exists(path):
            self.file_view.setRootIndex(self.file_model.index(path))

    def filter_explorer(self, text):
        if text.strip():
            self.file_model.setNameFilters([f"*{text}*"])
            self.file_model.setNameFilterDisables(False)
        else:
            self.file_model.setNameFilters([])

