    def get_steam_path(self):
        try:
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam")
            path, _ = winreg.QueryValueEx(key, "SteamPath")
            if os.path.exists(path):
                return path
        except Exception:
            pass
        for fb in [r"C:\Program Files (x86)\Steam", r"C:\Steam", r"D:\Steam"]:
            if os.path.exists(fb):
                return fb
        return None

    def find_steam_avatar(self, steam_base, steam_id):
        cache_dir = os.path.join(steam_base, "config", "avatarcache")
        for ext in (".png", ".jpg", ".jpeg"):
            candidate = os.path.join(cache_dir, steam_id + ext)
            if os.path.isfile(candidate):
                return candidate
        if os.path.isdir(cache_dir):
            try:
                for fname in os.listdir(cache_dir):
                    if steam_id in fname and fname.lower().endswith((".png", ".jpg", ".jpeg")):
                        return os.path.join(cache_dir, fname)
            except OSError:
                pass
        return None

    def make_avatar_pixmap(self, path, size):
        src = QPixmap(path)
        if src.isNull():
            return None
        scaled = src.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
        x = (scaled.width() - size) // 2
        y = (scaled.height() - size) // 2
        scaled = scaled.copy(x, y, size, size)

        result = QPixmap(size, size)
        result.fill(Qt.GlobalColor.transparent)
        painter = QPainter(result)
        try:
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            clip = QPainterPath()
            clip.addRoundedRect(0.0, 0.0, float(size), float(size), 10.0, 10.0)
            painter.setClipPath(clip)
            painter.drawPixmap(0, 0, scaled)
            painter.setClipping(False)
            pen = QPen(QColor("#30363d"))
            pen.setWidth(1)
            painter.setPen(pen)
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.drawRoundedRect(QRectF(0.5, 0.5, size - 1.0, size - 1.0), 10.0, 10.0)
        finally:
            painter.end()
        return result

    def copy_steam_id(self, steam_id, button):
        QApplication.clipboard().setText(steam_id)
        button.setText("Copied!")
        QTimer.singleShot(1200, lambda: button.setText("Copy ID"))

    def open_in_steam(self, steam_id):
        try:
            os.startfile(f"steam://openurl/https://steamcommunity.com/profiles/{steam_id}")
        except Exception as e:
            QMessageBox.warning(self, "Steam", f"Could not open Steam: {str(e)}")

    def load_steam_accounts(self):
        while self.steam_grid.count():
            item = self.steam_grid.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()

        steam_base = self.get_steam_path()
        if not steam_base:
            self.steam_grid.addWidget(QLabel("Steam directory could not be located."), 0, 0)
            return

        vdf_path = os.path.join(steam_base, "config", "loginusers.vdf")
        if not os.path.exists(vdf_path):
            self.steam_grid.addWidget(QLabel("loginusers.vdf missing."), 0, 0)
            return

        try:
            with open(vdf_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                
            accounts = re.findall(r'"(\d{17})"\s*\{([^}]*)\}', content)
            if not accounts:
                self.steam_grid.addWidget(QLabel("No registered Steam accounts found."), 0, 0)
                return

            max_cols = 2
            row, col = 0, 0
            avatar_size = 64
            btn_style = (
                "QPushButton { padding: 0px; font-size: 12px; font-weight: bold; color: #c9d1d9;"
                " background-color: #21262d; border: 1px solid #444c56; border-radius: 6px; }"
                "QPushButton:hover { background-color: #30363d; border-color: #ffffff; color: #ffffff; }"
                "QPushButton:pressed { background-color: #161b22; }"
            )

            for steam_id, data in accounts:
                name_match = re.search(r'"AccountName"\s*"([^"]+)"', data)
                persona_match = re.search(r'"PersonaName"\s*"([^"]+)"', data)

                acc_name = name_match.group(1) if name_match else "Unknown"
                persona_name = persona_match.group(1) if persona_match else "Unknown"

                card = QFrame()
                card.setObjectName("steamCard")
                card.setFixedWidth(480)
                card.setStyleSheet(
                    "QFrame#steamCard { background-color: #161b22; border: 1px solid #30363d; border-radius: 10px; }"
                )
                card_vbox = QVBoxLayout(card)
                card_vbox.setContentsMargins(16, 14, 16, 14)
                card_vbox.setSpacing(12)

                top_row = QHBoxLayout()
                top_row.setSpacing(14)

                avatar_lbl = QLabel()
                avatar_lbl.setFixedSize(avatar_size, avatar_size)
                avatar_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)

                avatar_pix = None
                avatar_path = self.find_steam_avatar(steam_base, steam_id)
                if avatar_path:
                    avatar_pix = self.make_avatar_pixmap(avatar_path, avatar_size)

                if avatar_pix is not None:
                    avatar_lbl.setPixmap(avatar_pix)
                    avatar_lbl.setStyleSheet("background: transparent; border: none;")
                else:
                    avatar_lbl.setText(persona_name[:2].upper())
                    avatar_lbl.setStyleSheet(
                        "background-color: #30363d; color: #ffffff; font-weight: bold;"
                        " font-size: 20px; border-radius: 10px;"
                    )

                top_row.addWidget(avatar_lbl)

                lbl_name = QLabel(persona_name)
                lbl_name.setFont(QFont("Segoe UI", 13, QFont.Weight.Bold))
                lbl_name.setStyleSheet("color: #ffffff; background: transparent; border: none;")
                top_row.addWidget(lbl_name, 1)
                card_vbox.addLayout(top_row)

                sub_row = QHBoxLayout()
                sub_row.setSpacing(6)
                lbl_id = QLabel(steam_id)
                lbl_id.setStyleSheet("color: #8b949e; font-family: Consolas; font-size: 12px; background: transparent; border: none;")

                btn_copy = QPushButton("Copy ID")
                btn_copy.setFixedSize(78, 30)
                btn_copy.setStyleSheet(btn_style)
                btn_copy.setCursor(Qt.CursorShape.PointingHandCursor)
                btn_copy.clicked.connect(lambda checked=False, sid=steam_id, b=btn_copy: self.copy_steam_id(sid, b))

                btn_browser = QPushButton("Browser")
                btn_browser.setFixedSize(78, 30)
                btn_browser.setStyleSheet(btn_style)
                btn_browser.setCursor(Qt.CursorShape.PointingHandCursor)
                btn_browser.clicked.connect(lambda checked=False, sid=steam_id: webbrowser.open(f"https://steamcommunity.com/profiles/{sid}"))

                btn_steam = QPushButton("Steam")
                btn_steam.setFixedSize(78, 30)
                btn_steam.setStyleSheet(btn_style)
                btn_steam.setCursor(Qt.CursorShape.PointingHandCursor)
                btn_steam.clicked.connect(lambda checked=False, sid=steam_id: self.open_in_steam(sid))

                sub_row.addWidget(lbl_id)
                sub_row.addStretch()
                sub_row.addWidget(btn_copy)
                sub_row.addWidget(btn_browser)
                sub_row.addWidget(btn_steam)
                card_vbox.addLayout(sub_row)

                info_grid = QHBoxLayout()
                lbl_login_title = QLabel("Account Login:")
                lbl_login_title.setStyleSheet("color: #8b949e; background: transparent; border: none;")
                info_grid.addWidget(lbl_login_title)
                info_grid.addStretch()
                r3_val = QLabel(acc_name)
                r3_val.setStyleSheet("color: #c9d1d9; font-weight: bold; background: transparent; border: none;")
                info_grid.addWidget(r3_val)
                card_vbox.addLayout(info_grid)

                self.steam_grid.addWidget(card, row, col)
                col += 1
                if col >= max_cols:
                    col = 0
                    row += 1

        except Exception as e:
            self.steam_grid.addWidget(QLabel(f"Error reading Steam accounts: {str(e)}"), 0, 0)

    def setup_processes_tab(self):
        layout = QVBoxLayout()
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)
        
        top_bar = QHBoxLayout()
        self.proc_search = QLineEdit()
        self.proc_search.setPlaceholderText("Filter processes by name or PID...")
        self.proc_search.textChanged.connect(self.filter_processes)
        top_bar.addWidget(self.proc_search)

        btn_refresh = QPushButton("Refresh")
        btn_refresh.clicked.connect(self.load_processes)
        top_bar.addWidget(btn_refresh)

        btn_kill = QPushButton("Kill Process")
        btn_kill.setObjectName("dangerBtn")
        btn_kill.clicked.connect(self.kill_process)
        top_bar.addWidget(btn_kill)
        
        layout.addLayout(top_bar)

        self.proc_table = QTableWidget()
        self.proc_table.setColumnCount(3)
        self.proc_table.setHorizontalHeaderLabels(["PID", "Process Name", "Executable Path"])
        self.proc_table.horizontalHeader().setSectionResizeMode(2, QHeaderView.ResizeMode.Stretch)
        self.proc_table.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        layout.addWidget(self.proc_table)

        self.tab_processes.setLayout(layout)
        self.load_processes()

    def load_processes(self):
        self.proc_table.setRowCount(0)
        for proc in psutil.process_iter(['pid', 'name', 'exe']):
            try:
                pinfo = proc.info
                row = self.proc_table.rowCount()
                self.proc_table.insertRow(row)
                
                self.proc_table.setItem(row, 0, QTableWidgetItem(str(pinfo['pid'])))
                self.proc_table.setItem(row, 1, QTableWidgetItem(str(pinfo['name'])))
                self.proc_table.setItem(row, 2, QTableWidgetItem(str(pinfo['exe'] or "")))
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                pass

    def filter_processes(self, text):
        query = text.lower()
        for row in range(self.proc_table.rowCount()):
            match = False
            for col in range(self.proc_table.columnCount()):
                item = self.proc_table.item(row, col)
                if item and query in item.text().lower():
                    match = True
                    break
            self.proc_table.setRowHidden(row, not match)

    def kill_process(self):
        selected_row = self.proc_table.currentRow()
        if selected_row >= 0:
            pid_item = self.proc_table.item(selected_row, 0)
            if pid_item:
                pid = int(pid_item.text())
                try:
                    p = psutil.Process(pid)
                    p.terminate()
                    self.load_processes()
                    QMessageBox.information(self, "Terminated", f"Process {pid} terminated successfully.")
                except Exception as e:
                    QMessageBox.critical(self, "Error", f"Could not kill process: {str(e)}")

    def setup_tools_tab(self):
        layout = QVBoxLayout()
        layout.setContentsMargins(20, 20, 20, 20)
        layout.setSpacing(10)

        header = QLabel("System Administrative Utilities & Shortcuts")
        header.setFont(QFont("Segoe UI", 11, QFont.Weight.Bold))
        layout.addWidget(header)

        btn_dns = QPushButton("Flush DNS Cache (ipconfig /flushdns)")
        btn_dns.clicked.connect(lambda: subprocess.run("ipconfig /flushdns", shell=True))
        layout.addWidget(btn_dns)

        btn_prefetch = QPushButton("Open Windows Prefetch Folder")
        btn_prefetch.clicked.connect(lambda: os.startfile(r'C:\Windows\Prefetch') if os.path.exists(r'C:\Windows\Prefetch') else None)
        layout.addWidget(btn_prefetch)

        btn_temp = QPushButton("Open Local Temp Folder")
        btn_temp.clicked.connect(lambda: os.startfile(os.path.expandvars(r'%TEMP%')))
        layout.addWidget(btn_temp)

        btn_hosts = QPushButton("Open Windows Hosts File")
        btn_hosts.clicked.connect(lambda: os.startfile(r'C:\Windows\System32\drivers\etc\hosts') if os.path.exists(r'C:\Windows\System32\drivers\etc\hosts') else None)
        layout.addWidget(btn_hosts)

        btn_netstat = QPushButton("View Active Network Connections (Netstat)")
        btn_netstat.clicked.connect(lambda: subprocess.run("start cmd /k netstat -ano", shell=True))
        layout.addWidget(btn_netstat)

        layout.addStretch()
        self.tab_tools.setLayout(layout)

