        desc = QLabel(
            "<b>SpectreLine v1.0</b> is a system inspection and auditing tool designed for deep file structure analysis, "
            "process monitoring, and quick verification of system components.<br><br>"
            "<b>Purpose & Usage:</b><br>"
            "The tool can be effectively utilized by administrators on public Counter-Strike 2 servers and gaming communities "
            "to perform quick, reliable inspections, verify local file paths, inspect shortcuts (.lnk targets), and review running processes.<br><br>"
            "<b>Key Features:</b>"
            "<ul>"
            "<li><b>Drive / Scan:</b> Deep search across disks, directories, files, and shortcut binary targets.</li>"
            "<li><b>File Explorer:</b> Built-in directory navigator with quick access filters.</li>"
            "<li><b>Steam Accounts:</b> Automatic local Steam account detection and avatar caching.</li>"
            "<li><b>Processes:</b> Active Windows process monitoring and management.</li>"
            "<li><b>Utilities:</b> Essential system shortcuts and administration tools.</li>"
            "</ul>"
            "<br><b>Version:</b> 1.0.0<br>"
            "<b>Developer:</b> Ilyukha211"
        )
        desc.setFont(QFont("Segoe UI", 11))
        desc.setWordWrap(True)
        desc.setStyleSheet("color: #c9d1d9;")
        desc.setTextFormat(Qt.TextFormat.RichText)
        layout.addWidget(desc)

        self.git_image_lbl = QLabel()
        self.git_image_lbl.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        git_pix = load_git_pixmap()
        if not git_pix.isNull():
            git_pix = git_pix.scaled(260, 72, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
            self.git_image_lbl.setPixmap(git_pix)
            self.git_image_lbl.setFixedSize(git_pix.size())
            self.git_image_lbl.setStyleSheet("background: transparent; border: none;")
        else:
            self.git_image_lbl.setText("git.png")
            self.git_image_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.git_image_lbl.setFixedSize(160, 56)
            self.git_image_lbl.setStyleSheet(
                "color: #484f58; border: 1px dashed #30363d; border-radius: 8px; background: transparent;"
            )

        self.github_link_lbl = QLabel(
            f'<a href="{GITHUB_URL}" style="color: #ffffff; text-decoration: none;">GitHub</a>'
        )
        self.github_link_lbl.setTextFormat(Qt.TextFormat.RichText)
        self.github_link_lbl.setOpenExternalLinks(True)  
        self.github_link_lbl.setCursor(Qt.CursorShape.PointingHandCursor)
        self.github_link_lbl.setToolTip(GITHUB_URL)
        self.github_link_lbl.setFont(QFont("Segoe UI", 14, QFont.Weight.Bold))
        self.github_link_lbl.setStyleSheet("background: transparent;")

        git_row = QHBoxLayout()
        git_row.setContentsMargins(0, 0, 0, 0)
        git_row.setSpacing(12)
        git_row.addWidget(self.git_image_lbl, 0, Qt.AlignmentFlag.AlignVCenter)
        git_row.addWidget(self.github_link_lbl, 0, Qt.AlignmentFlag.AlignVCenter)
        git_row.addStretch()
        layout.addLayout(git_row)

        layout.addStretch()
        self.tab_info.setLayout(layout)

